import React from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";

function TechnicalEvents() {
  const navigate = useNavigate();

  const events = [
    {
      id: 1,
      name: "Project Presentation",
      time: "9:30 AM - 12:30 PM",
      venue: "Room 107",
    },
    {
      id: 2,
      name: "Reverse Engineering",
      time: "9:30 AM - 12:30 PM",
      venue: "Room 114",
    },
    {
      id: 17,
      name: "Code Debugging",
      time: "1:00 PM - 4:30 PM",
      venue: "Room 224",
    },

    // ✅ New Events Added
    {
      id: 3,
      name: "Hackathon",
      time: "9:00 AM - 6:00 PM",
      venue: "Lab 1",
    },
    {
      id: 4,
      name: "Paper Presentation",
      time: "10:00 AM - 1:00 PM",
      venue: "Seminar Hall",
    },
    {
      id: 5,
      name: "Web Designing",
      time: "1:30 PM - 4:30 PM",
      venue: "Lab 2",
    },
    {
      id: 6,
      name: "App Development",
      time: "9:30 AM - 12:30 PM",
      venue: "Lab 3",
    },
    {
      id: 7,
      name: "AI Quiz",
      time: "11:00 AM - 12:30 PM",
      venue: "Room 210",
    },
    {
      id: 8,
      name: "Cyber Security Challenge",
      time: "2:00 PM - 5:00 PM",
      venue: "Lab 4",
    },
    {
      id: 9,
      name: "Coding Contest",
      time: "10:00 AM - 1:00 PM",
      venue: "Lab 5",
    },
    {
      id: 10,
      name: "UI/UX Design",
      time: "1:00 PM - 3:30 PM",
      venue: "Room 118",
    },
    {
      id: 11,
      name: "Cloud Computing Workshop",
      time: "9:30 AM - 12:30 PM",
      venue: "Room 305",
    },
    {
      id: 12,
      name: "Robotics Demo",
      time: "2:00 PM - 4:00 PM",
      venue: "Lab 6",
    },
    {
      id: 13,
      name: "Data Science Challenge",
      time: "10:30 AM - 1:30 PM",
      venue: "Room 220",
    },
  ];

  const handleRegister = (event) => {
    navigate("/register", {
      state: {
        eventId: event.id,
        eventName: event.name,
      },
    });
  };

  return (
    <div>
      <Navbar />
      <h2 style={{ textAlign: "center" }}>Technical Events</h2>

      <div style={{ display: "grid", gap: "20px", padding: "20px" }}>
        {events.map((event) => (
          <div key={event.id} style={{ border: "1px solid #ccc", padding: "15px" }}>
            <h3>{event.name}</h3>
            <p><b>Time:</b> {event.time}</p>
            <p><b>Venue:</b> {event.venue}</p>

            <button onClick={() => handleRegister(event)}>
              Register
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default TechnicalEvents;
